const PV_EX = [
  /* ===================== MOBILIZZAZIONE ===================== */
  { id: "m01", n: "Circonduzioni delle spalle", b: "mob", z: ["spalla"], eq: "none", lv: 1, t: "r", q: 10, d: "In piedi, braccia rilassate lungo i fianchi. Disegna cerchi ampi con le spalle: 10 in avanti e 10 indietro.", k: "Movimento lento, senza alzare il mento." },
  { id: "m02", n: "Circonduzioni delle braccia", b: "mob", z: ["spalla"], eq: "none", lv: 1, t: "s", q: 40, d: "Braccia tese di lato, cerchi piccoli che diventano via via più ampi. A metà tempo cambia senso.", k: "Addome attivo, schiena dritta." },
  { id: "m03", n: "Apertura del libro", b: "mob", z: ["spalla", "lombare"], eq: "none", lv: 1, t: "r", q: 8, u: 1, tp: 4, d: "Sdraiato sul fianco, ginocchia piegate a 90°, braccia tese davanti. Apri il braccio di sopra verso l'altro lato seguendolo con lo sguardo, poi torna.", k: "Le ginocchia restano unite e appoggiate a terra." },
  { id: "m04", n: "Scivolamenti al muro", b: "mob", z: ["spalla"], eq: "none", lv: 1, t: "r", q: 10, tp: 4, d: "Schiena e braccia appoggiate al muro, gomiti piegati a W. Fai scivolare le braccia verso l'alto fino a formare una Y, poi torna giù.", k: "Fermati prima che la schiena si stacchi dal muro." },
  { id: "m05", n: "Rotazioni del dorso a quattro zampe", b: "mob", z: ["spalla", "lombare"], eq: "none", lv: 1, t: "r", q: 8, u: 1, tp: 4, d: "A quattro zampe, una mano dietro la testa. Porta il gomito verso il braccio d'appoggio, poi ruota aprendo il gomito verso il soffitto.", k: "Il bacino resta fermo, ruota solo il busto." },
  { id: "m06", n: "Gatto e mucca", b: "mob", z: ["lombare"], eq: "none", lv: 1, t: "r", q: 10, tp: 4, d: "A quattro zampe, mani sotto le spalle e ginocchia sotto le anche. Alterna schiena arrotondata (sguardo all'ombelico) e schiena incavata (sguardo avanti).", k: "Accompagna il movimento con il respiro." },
  { id: "m07", n: "Passaggi sopra la testa con asciugamano", b: "mob", z: ["spalla"], eq: "none", lv: 1, t: "r", q: 10, tp: 4, d: "Tieni un asciugamano teso con presa larga. Porta le braccia tese da davanti alle cosce fin dietro la schiena passando sopra la testa, poi torna.", k: "Se senti tirare troppo, allarga la presa." },
  { id: "m08", n: "Passaggi sopra la testa con elastico", b: "mob", z: ["spalla"], eq: "elastico", lv: 1, t: "r", q: 10, tp: 4, d: "Come con l'asciugamano, ma con un elastico leggero tenuto a presa larga: braccia tese da davanti fin dietro, passando sopra la testa.", k: "Braccia sempre tese, movimento continuo." },
  { id: "m09", n: "Circonduzioni controllate della spalla", b: "mob", z: ["spalla"], eq: "none", lv: 1, t: "r", q: 5, u: 1, tp: 6, d: "In piedi, pugno chiuso e resto del corpo fermo. Porta il braccio teso avanti, in alto, dietro e giù, disegnando il cerchio più ampio possibile, lentamente.", k: "Solo la spalla si muove: il busto non ruota." },
  { id: "m10", n: "Infila l'ago", b: "mob", z: ["spalla", "lombare"], eq: "none", lv: 1, t: "r", q: 6, u: 1, tp: 5, d: "A quattro zampe. Fai scivolare un braccio sotto il corpo verso il lato opposto, appoggiando la spalla a terra, poi riaprilo verso il soffitto.", k: "Respira durante la rotazione." },
  { id: "m11", n: "Rotazioni a 90° senza carico", b: "mob", z: ["spalla"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 3, d: "Braccio alzato di lato all'altezza della spalla, gomito piegato a 90° (come nella posizione del servizio). Ruota l'avambraccio in alto e in basso.", k: "Gomito fermo all'altezza della spalla." },
  { id: "m12", n: "Circonduzioni dei polsi", b: "mob", z: ["polso"], eq: "none", lv: 1, t: "s", q: 30, d: "Dita intrecciate, disegna cerchi lenti con i polsi in un senso e poi nell'altro.", k: "Spalle rilassate." },
  { id: "m13", n: "Dondolii sui palmi", b: "mob", z: ["polso", "gomito"], eq: "none", lv: 2, t: "r", q: 10, tp: 3, d: "A quattro zampe, palmi a terra. Sposta piano il peso avanti e indietro sopra le mani. Poi ripeti con le dita rivolte verso le ginocchia, con poco peso.", k: "Carica solo quanto è comodo." },
  { id: "m14", n: "Rotazioni dell'avambraccio", b: "mob", z: ["gomito", "polso"], eq: "none", lv: 1, t: "r", q: 15, tp: 2, d: "Gomiti piegati a 90° vicino ai fianchi. Gira i palmi verso l'alto e verso il basso.", k: "I gomiti non si staccano dai fianchi." },
  { id: "m15", n: "Apri e chiudi le mani", b: "mob", z: ["polso"], eq: "none", lv: 1, t: "s", q: 30, d: "Braccia avanti, apri bene le dita e chiudi il pugno senza stringere, a ritmo regolare.", k: "Apertura completa delle dita." },
  { id: "m16", n: "Apri e chiudi il cancello", b: "mob", z: ["anca"], eq: "none", lv: 1, t: "r", q: 8, u: 1, tp: 4, d: "In piedi, con un appoggio se serve. Alza il ginocchio davanti e ruotalo verso l'esterno (apri il cancello), poi fai il percorso inverso (chiudi).", k: "Busto dritto, bacino fermo." },
  { id: "m17", n: "Rotazioni dell'anca 90/90", b: "mob", z: ["anca"], eq: "none", lv: 1, t: "r", q: 8, tp: 4, d: "Seduto a terra, mani dietro di te, piedi più larghi delle anche e ginocchia piegate. Lascia cadere entrambe le ginocchia da un lato, poi dall'altro.", k: "Movimento lento, senza forzare la fine." },
  { id: "m18", n: "Affondo con rotazione del busto", b: "mob", z: ["anca", "lombare", "spalla"], eq: "none", lv: 2, t: "r", q: 5, u: 1, tp: 6, d: "Affondo lungo in avanti, mano opposta a terra. Porta il gomito interno verso il piede davanti, poi ruota aprendo il braccio verso il soffitto.", k: "Il ginocchio davanti resta sopra la caviglia." },
  { id: "m19", n: "Oscillazioni della gamba avanti e indietro", b: "mob", z: ["anca"], eq: "none", lv: 1, t: "r", q: 12, u: 1, tp: 2, d: "Una mano al muro. Lascia oscillare la gamba avanti e indietro, con ampiezza che cresce poco a poco.", k: "Busto fermo, gamba rilassata." },
  { id: "m20", n: "Oscillazioni laterali della gamba", b: "mob", z: ["anca"], eq: "none", lv: 1, t: "r", q: 12, u: 1, tp: 2, d: "Di fronte al muro con le mani appoggiate. Oscilla la gamba di lato, davanti alla gamba d'appoggio e verso l'esterno.", k: "Bacino rivolto al muro." },
  { id: "m21", n: "Ginocchio verso il muro", b: "mob", z: ["caviglia", "achille"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 3, d: "Di fronte al muro, un piede a qualche centimetro dal muro. Porta il ginocchio a toccare il muro tenendo il tallone a terra, poi torna.", k: "Il tallone non si stacca; il ginocchio va in linea con il secondo dito." },
  { id: "m22", n: "Circonduzioni delle caviglie", b: "mob", z: ["caviglia"], eq: "none", lv: 1, t: "s", q: 30, d: "Seduto o in piedi con appoggio, disegna cerchi lenti con la punta del piede, in entrambi i sensi e con entrambi i piedi.", k: "Cerchi grandi e lenti." },
  { id: "m23", n: "Camminata con le mani", b: "mob", z: ["lombare", "spalla", "achille"], eq: "none", lv: 2, t: "r", q: 5, tp: 8, d: "In piedi, piegati e appoggia le mani a terra (piega le ginocchia se serve). Cammina con le mani in avanti fino alla posizione di plank, poi torna indietro con le mani e risali.", k: "Addome attivo in posizione di plank." },
  { id: "m24", n: "Squat profondo con apertura", b: "mob", z: ["anca", "ginocchio", "caviglia"], eq: "none", lv: 1, t: "r", q: 6, tp: 6, d: "Piedi poco più larghi delle spalle. Scendi in squat profondo, gomiti all'interno delle ginocchia per aprirle dolcemente, resta 2 secondi e risali.", k: "Talloni a terra; scendi solo quanto è comodo." },
  { id: "m25", n: "Rotazioni del busto in piedi", b: "mob", z: ["lombare"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 2, d: "Piedi alla larghezza delle spalle, braccia morbide. Ruota il busto a destra e a sinistra lasciando seguire le braccia.", k: "Ginocchia morbide, bacino quasi fermo." },
  { id: "m26", n: "Ginocchia al petto in camminata", b: "mob", z: ["anca", "lombare"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 3, d: "Camminando, porta un ginocchio al petto aiutandoti con le mani, sali sulla punta dell'altro piede e riparti.", k: "Busto dritto." },
  { id: "m27", n: "Talloni ai glutei dinamici", b: "mob", z: ["ginocchio"], eq: "none", lv: 1, t: "s", q: 30, d: "Sul posto o camminando, porta in modo alternato il tallone verso il gluteo, a ritmo tranquillo.", k: "Ginocchia che puntano in basso." },
  { id: "m28", n: "Basculamento del bacino", b: "mob", z: ["lombare", "core"], eq: "none", lv: 1, t: "r", q: 10, tp: 4, d: "Sdraiato sulla schiena, ginocchia piegate. Schiaccia piano la zona lombare a terra, poi crea un piccolo arco. Movimento piccolo e lento.", k: "Muovi solo il bacino, spalle rilassate." },
  { id: "m29", n: "Tergicristallo", b: "mob", z: ["lombare", "anca"], eq: "none", lv: 1, t: "r", q: 10, tp: 4, d: "Sdraiato sulla schiena, ginocchia piegate e unite, braccia aperte. Lascia cadere le ginocchia da un lato e poi dall'altro.", k: "Le spalle restano appoggiate." },
  { id: "m30", n: "Estensione da prono (cobra)", b: "mob", z: ["lombare"], eq: "none", lv: 1, t: "r", q: 8, tp: 4, d: "A pancia in giù, mani sotto le spalle. Spingi piano sollevando il busto e lascia il bacino a terra, poi scendi.", k: "Sali solo fin dove è comodo." },
  { id: "m31", n: "Dondolo verso i talloni", b: "mob", z: ["anca", "lombare"], eq: "none", lv: 1, t: "r", q: 10, tp: 3, d: "A quattro zampe, porta il bacino indietro verso i talloni mantenendo la schiena neutra, poi torna avanti.", k: "Schiena lunga, non arrotondarla." },
  { id: "m32", n: "Flesso-estensione del ginocchio da seduto", b: "mob", z: ["ginocchio"], eq: "none", lv: 1, t: "r", q: 15, u: 1, tp: 2, d: "Seduto su una sedia, distendi lentamente la gamba e poi piegala portando il piede sotto la sedia.", k: "Movimento fluido, senza scatti." },
  { id: "m33", n: "Scivolamento del tallone", b: "mob", z: ["ginocchio", "anca"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 4, d: "Sdraiato sulla schiena, fai scivolare il tallone verso il gluteo piegando il ginocchio, poi distendi.", k: "Fermati dove il movimento è comodo." },
  { id: "m34", n: "Alfabeto con la caviglia", b: "mob", z: ["caviglia"], eq: "none", lv: 1, t: "s", q: 40, u: 1, d: "Seduto con la gamba sollevata, scrivi le lettere dell'alfabeto in aria con la punta del piede.", k: "Muovi la caviglia, non la gamba." },
  { id: "m35", n: "Camminata sulle punte", b: "mob", z: ["achille", "caviglia"], eq: "none", lv: 1, t: "s", q: 30, d: "Cammina alto sulle punte dei piedi, a piccoli passi.", k: "Talloni alti, busto dritto." },
  { id: "m36", n: "Camminata sui talloni", b: "mob", z: ["tibia", "caviglia"], eq: "none", lv: 1, t: "s", q: 30, d: "Cammina sui talloni con le punte sollevate, a piccoli passi.", k: "Punte più alte possibile." },
  { id: "m37", n: "Skip basso", b: "mob", z: ["caviglia", "achille", "ginocchio"], eq: "none", lv: 2, t: "s", q: 30, d: "Corsa sul posto con passi brevi e rapidi sugli avampiedi, ginocchia poco sollevate, braccia che accompagnano.", k: "Appoggi leggeri e veloci." },
  { id: "m38", n: "Inclinazioni laterali del busto", b: "mob", z: ["lombare"], eq: "none", lv: 1, t: "r", q: 8, u: 1, tp: 3, d: "In piedi, piedi alla larghezza delle spalle. Fai scivolare una mano lungo la coscia inclinandoti di lato, poi torna.", k: "Non ruotare il busto, solo inclinazione." },
  { id: "m39", n: "Circonduzioni dell'anca a quattro zampe", b: "mob", z: ["anca"], eq: "none", lv: 2, t: "r", q: 5, u: 1, tp: 6, d: "A quattro zampe, solleva un ginocchio di lato, portalo indietro e in alto e poi in avanti, disegnando il cerchio più ampio possibile.", k: "Il resto del corpo resta immobile." },
  { id: "m40", n: "Pianta del piede sulla pallina", b: "mob", z: ["caviglia"], eq: "none", lv: 1, t: "s", q: 40, u: 1, d: "Seduto o in piedi con appoggio, fai rotolare una pallina da tennis sotto la pianta del piede, dal tallone alle dita.", k: "Pressione piacevole, non dolorosa." },
  { id: "m41", n: "Torsione da seduto", b: "mob", z: ["lombare", "spalla"], eq: "none", lv: 1, t: "r", q: 8, u: 1, tp: 4, d: "Seduto su una sedia con i piedi a terra, braccia incrociate sul petto. Ruota il busto da un lato e poi dall'altro.", k: "Cresci in altezza prima di ruotare." },
  { id: "m42", n: "Affondo laterale dinamico", b: "mob", z: ["anca", "ginocchio"], eq: "none", lv: 1, t: "r", q: 6, u: 1, tp: 4, d: "Piedi larghi. Sposta il peso su una gamba piegandola, l'altra resta tesa. Torna al centro e cambia lato.", k: "Il ginocchio piegato segue la punta del piede." },
  { id: "m43", n: "Mobilità del collo", b: "mob", z: ["spalla"], eq: "none", lv: 1, t: "r", q: 5, u: 1, tp: 4, d: "Seduto o in piedi, spalle basse. Gira lentamente la testa a destra e a sinistra, poi porta l'orecchio verso la spalla.", k: "Movimenti lenti e piccoli." },

  /* ===================== POTENZIAMENTO ===================== */
  /* spalle e scapole */
  { id: "p01", n: "Rotazione esterna con elastico", b: "pot", z: ["spalla"], eq: "elastico", lv: 1, t: "r", q: 12, u: 1, tp: 3, d: "Elastico fissato all'altezza del gomito. Gomito piegato a 90° vicino al fianco (puoi tenere un asciugamano arrotolato sotto l'ascella). Ruota l'avambraccio verso l'esterno e torna lentamente.", k: "Il gomito resta incollato al fianco." },
  { id: "p02", n: "Rotazione interna con elastico", b: "pot", z: ["spalla"], eq: "elastico", lv: 1, t: "r", q: 12, u: 1, tp: 3, d: "Elastico fissato di lato all'altezza del gomito. Gomito a 90° vicino al fianco, porta l'avambraccio verso la pancia e torna piano.", k: "Ritorno lento, in 2-3 secondi." },
  { id: "p03", n: "Rotazione esterna a 90° con elastico", b: "pot", z: ["spalla"], eq: "elastico", lv: 2, t: "r", q: 10, u: 1, tp: 3, d: "Elastico fissato davanti a te. Braccio alzato di lato all'altezza della spalla, gomito a 90° (posizione del servizio). Ruota la mano verso l'alto e torna.", k: "Gomito fermo all'altezza della spalla." },
  { id: "p04", n: "Apertura con elastico", b: "pot", z: ["spalla"], eq: "elastico", lv: 1, t: "r", q: 15, tp: 3, d: "Braccia tese davanti all'altezza delle spalle, elastico tra le mani. Apri le braccia avvicinando le scapole, poi torna piano.", k: "Spalle lontane dalle orecchie." },
  { id: "p05", n: "Remata con elastico", b: "pot", z: ["spalla", "lombare"], eq: "elastico", lv: 1, t: "r", q: 12, tp: 3, d: "Elastico fissato davanti all'altezza del petto. Tira verso di te portando i gomiti indietro vicino ai fianchi, stringi le scapole e torna.", k: "Petto aperto, non inarcare la schiena." },
  { id: "p06", n: "Y-T-W a terra", b: "pot", z: ["spalla"], eq: "none", lv: 1, t: "r", q: 6, tp: 9, d: "A pancia in giù, fronte su un asciugamano. Solleva le braccia formando una Y, poi una T, poi una W (gomiti piegati). Ogni ripetizione comprende le tre lettere.", k: "Pollici verso l'alto, collo lungo." },
  { id: "p07", n: "Y-T-W con manubri leggeri", b: "pot", z: ["spalla"], eq: "manubri", lv: 2, t: "r", q: 6, tp: 9, d: "Busto inclinato in avanti con la schiena dritta, manubri molto leggeri. Solleva le braccia a Y, poi a T, poi a W.", k: "Carico leggero: conta la qualità del movimento." },
  { id: "p08", n: "Rotazione esterna sul fianco con manubrio", b: "pot", z: ["spalla"], eq: "manubri", lv: 1, t: "r", q: 12, u: 1, tp: 3, d: "Sdraiato sul fianco, gomito del braccio di sopra piegato a 90° e appoggiato al fianco, manubrio leggero. Ruota l'avambraccio verso l'alto e scendi lentamente.", k: "Gomito fermo sul fianco." },
  { id: "p09", n: "Rematore con manubrio", b: "pot", z: ["spalla", "lombare"], eq: "manubri", lv: 1, t: "r", q: 10, u: 1, tp: 3, d: "Una mano e un ginocchio appoggiati su una panca o una sedia, schiena piatta. Tira il manubrio verso il fianco e scendi lentamente.", k: "Il gomito sfiora il fianco." },
  { id: "p10", n: "Piegamenti al muro con spinta delle scapole", b: "pot", z: ["spalla", "core"], eq: "none", lv: 1, t: "r", q: 10, tp: 3, d: "Mani al muro all'altezza delle spalle. Fai un piegamento e, a braccia tese, spingi ancora un po' allontanando le scapole tra loro.", k: "Corpo dritto dalla testa ai talloni." },
  { id: "p11", n: "Piegamenti sulle braccia", b: "pot", z: ["spalla", "core"], eq: "none", lv: 2, t: "r", q: 8, tp: 3, d: "Mani poco più larghe delle spalle, corpo in linea. Scendi con il petto verso terra e risali. Versione più facile: ginocchia a terra.", k: "Gomiti a circa 45° dal busto." },
  { id: "p12", n: "Plank con tocco della spalla", b: "pot", z: ["core", "spalla"], eq: "none", lv: 2, t: "r", q: 10, u: 1, tp: 2, d: "In plank sulle mani, piedi un po' larghi. Tocca la spalla opposta con una mano, alternando, senza far oscillare il bacino.", k: "Bacino fermo come un tavolo." },
  { id: "p13", n: "Distensione sopra la testa con manubri", b: "pot", z: ["spalla"], eq: "manubri", lv: 2, t: "r", q: 10, tp: 3, d: "In piedi, manubri all'altezza delle spalle. Spingi verso l'alto fino a braccia tese e scendi lentamente.", k: "Addome e glutei attivi, non inarcare." },
  { id: "p14", n: "Tirata al viso con elastico", b: "pot", z: ["spalla"], eq: "elastico", lv: 2, t: "r", q: 12, tp: 3, d: "Elastico fissato all'altezza degli occhi. Tira verso il viso aprendo i gomiti in alto e ruotando le mani indietro, poi torna.", k: "Gomiti alti, scapole che si avvicinano." },
  { id: "p15", n: "Diagonale con elastico dal basso in alto", b: "pot", z: ["spalla", "core"], eq: "elastico", lv: 2, t: "r", q: 10, u: 1, tp: 3, d: "Elastico fissato in basso dal lato opposto. Parti con la mano vicino all'anca opposta e tira in diagonale verso l'alto e l'esterno, come per sguainare una spada.", k: "Il busto accompagna, senza ruotare troppo." },
  { id: "p16", n: "Scapole indietro e in basso", b: "pot", z: ["spalla"], eq: "none", lv: 1, t: "r", q: 10, tp: 5, d: "In piedi o seduto, braccia lungo i fianchi. Porta le scapole indietro e in basso, tieni 3 secondi e rilascia.", k: "Non alzare le spalle." },
  { id: "p17", n: "Rotazione esterna isometrica al muro", b: "pot", z: ["spalla"], eq: "none", lv: 1, t: "r", q: 5, u: 1, tp: 12, d: "Di fianco a una porta o al muro, gomito a 90° vicino al fianco. Spingi il dorso della mano contro il muro verso l'esterno con forza moderata per 10 secondi, senza muovere il braccio.", k: "Forza moderata, senza dolore." },
  /* gomiti, avambracci e polsi */
  { id: "p20", n: "Estensione del polso lenta con manubrio", b: "pot", z: ["gomito", "polso"], eq: "manubri", lv: 1, t: "r", q: 12, u: 1, tp: 5, d: "Avambraccio appoggiato sulla coscia, palmo in giù, manubrio leggero. Aiutati con l'altra mano a portare il polso in alto, poi scendi da solo lentamente in 3-4 secondi.", k: "La discesa lenta è la parte importante." },
  { id: "p21", n: "Flessione del polso con manubrio", b: "pot", z: ["gomito", "polso"], eq: "manubri", lv: 1, t: "r", q: 12, u: 1, tp: 3, d: "Avambraccio appoggiato sulla coscia, palmo in su, manubrio leggero. Piega il polso verso l'alto e scendi lentamente.", k: "Muove solo il polso." },
  { id: "p22", n: "Prono-supinazione con manubrio", b: "pot", z: ["gomito", "polso"], eq: "manubri", lv: 1, t: "r", q: 10, u: 1, tp: 4, d: "Avambraccio sulla coscia, tieni il manubrio da un'estremità (o un martello). Ruota lentamente il palmo verso l'alto e verso il basso.", k: "Più la presa è lontana dal peso, più è facile." },
  { id: "p23", n: "Sollevamento del polso a martello", b: "pot", z: ["polso", "gomito"], eq: "manubri", lv: 2, t: "r", q: 12, u: 1, tp: 3, d: "In piedi, braccio lungo il fianco, tieni il manubrio da un'estremità con il peso davanti. Solleva la punta del peso piegando solo il polso, poi scendi.", k: "Il braccio resta fermo." },
  { id: "p24", n: "Estensione del polso con elastico", b: "pot", z: ["gomito", "polso"], eq: "elastico", lv: 1, t: "r", q: 15, u: 1, tp: 3, d: "Seduto, piede sopra l'elastico, avambraccio sulla coscia e palmo in giù. Porta il polso in alto e torna lentamente.", k: "Ritorno lento." },
  { id: "p25", n: "Stringi la pallina", b: "pot", z: ["polso", "gomito"], eq: "none", lv: 1, t: "r", q: 12, u: 1, tp: 4, d: "Stringi una pallina da tennis nel palmo per 3 secondi con forza moderata, poi rilascia.", k: "Forza moderata, spalla rilassata." },
  { id: "p26", n: "Apertura delle dita con elastico", b: "pot", z: ["polso", "gomito"], eq: "elastico", lv: 1, t: "r", q: 15, u: 1, tp: 2, d: "Metti un elastico leggero (anche da cucina) intorno alle dita e al pollice. Apri le dita contro la resistenza e chiudi lentamente.", k: "Apri tutte le dita insieme." },
  { id: "p27", n: "Curl con manubri", b: "pot", z: ["gomito"], eq: "manubri", lv: 1, t: "r", q: 12, tp: 3, d: "In piedi, manubri lungo i fianchi con i palmi in avanti. Piega i gomiti portando i pesi verso le spalle e scendi lentamente.", k: "Gomiti fermi vicino al busto." },
  { id: "p28", n: "Curl a martello", b: "pot", z: ["gomito", "polso"], eq: "manubri", lv: 1, t: "r", q: 12, tp: 3, d: "Come il curl, ma con i palmi rivolti verso il corpo (presa a martello).", k: "Polsi dritti." },
  { id: "p29", n: "Estensione dei tricipiti con elastico", b: "pot", z: ["gomito"], eq: "elastico", lv: 1, t: "r", q: 12, tp: 3, d: "Elastico fissato in alto. Gomiti vicino ai fianchi, distendi le braccia verso il basso e torna piano.", k: "Muovono solo gli avambracci." },
  { id: "p30", n: "Estensione del polso isometrica", b: "pot", z: ["gomito", "polso"], eq: "none", lv: 1, t: "r", q: 5, u: 1, tp: 12, d: "Avambraccio appoggiato sul tavolo, palmo in giù. Con l'altra mano premi sul dorso della mano mentre provi a sollevarla: tieni 10 secondi senza muoverti.", k: "Spinta moderata e costante." },
  /* tronco e core */
  { id: "p40", n: "Plank", b: "pot", z: ["core", "lombare"], eq: "none", lv: 1, t: "s", q: 25, d: "Avambracci a terra sotto le spalle, corpo dritto dalla testa ai talloni. Versione facile: ginocchia a terra.", k: "Non lasciare cadere il bacino." },
  { id: "p41", n: "Plank laterale sulle ginocchia", b: "pot", z: ["core", "lombare", "spalla"], eq: "none", lv: 1, t: "s", q: 20, u: 1, d: "Sul fianco, avambraccio sotto la spalla, ginocchia piegate. Solleva il bacino formando una linea da testa a ginocchia.", k: "Bacino alto, spalla lontana dall'orecchio." },
  { id: "p42", n: "Plank laterale", b: "pot", z: ["core", "lombare", "anca"], eq: "none", lv: 2, t: "s", q: 25, u: 1, d: "Sul fianco, avambraccio sotto la spalla, gambe tese e piedi uno sull'altro (o uno davanti all'altro). Solleva il bacino e tieni.", k: "Corpo in linea, non ruotare." },
  { id: "p43", n: "Dead bug", b: "pot", z: ["core", "lombare"], eq: "none", lv: 1, t: "r", q: 8, u: 1, tp: 4, d: "Sdraiato sulla schiena, braccia verso il soffitto e ginocchia a 90° sopra le anche. Distendi lentamente braccio e gamba opposti verso terra, poi torna.", k: "La zona lombare resta appoggiata." },
  { id: "p44", n: "Quadrupedia alternata", b: "pot", z: ["core", "lombare", "anca"], eq: "none", lv: 1, t: "r", q: 8, u: 1, tp: 5, d: "A quattro zampe, distendi braccio e gamba opposti fino a formare una linea, tieni 2 secondi e torna.", k: "Bacino fermo, come se avessi un bicchiere sulla schiena." },
  { id: "p45", n: "Ponte per i glutei", b: "pot", z: ["anca", "lombare"], eq: "none", lv: 1, t: "r", q: 12, tp: 4, d: "Sdraiato sulla schiena, ginocchia piegate, piedi a terra. Solleva il bacino stringendo i glutei, tieni 1 secondo e scendi lentamente.", k: "Spingi con i talloni, non inarcare." },
  { id: "p46", n: "Ponte su una gamba", b: "pot", z: ["anca", "lombare", "ginocchio"], eq: "none", lv: 2, t: "r", q: 8, u: 1, tp: 4, d: "Come il ponte, ma con una gamba distesa in aria. Solleva il bacino spingendo con il tallone a terra.", k: "Il bacino resta orizzontale." },
  { id: "p47", n: "Spinta antirotazione con elastico", b: "pot", z: ["core", "lombare"], eq: "elastico", lv: 1, t: "r", q: 10, u: 1, tp: 4, d: "Di fianco al punto in cui è fissato l'elastico, mani al petto. Spingi le mani in avanti a braccia tese resistendo alla rotazione, tieni 2 secondi e torna.", k: "Il busto non deve ruotare verso l'elastico." },
  { id: "p48", n: "Legnaiolo con elastico", b: "pot", z: ["core", "spalla", "lombare"], eq: "elastico", lv: 2, t: "r", q: 10, u: 1, tp: 3, d: "Elastico fissato in alto di lato. Con le due mani tira in diagonale dall'alto verso il fianco opposto, ruotando busto e anche insieme.", k: "Il movimento parte dalle anche." },
  { id: "p49", n: "Rotazione del busto con manubrio", b: "pot", z: ["core", "lombare"], eq: "manubri", lv: 2, t: "r", q: 10, u: 1, tp: 3, d: "Seduto, ginocchia piegate e piedi a terra, busto leggermente inclinato indietro. Tieni un manubrio al petto e ruota il busto da un lato all'altro.", k: "Schiena dritta, movimento controllato." },
  { id: "p50", n: "Superman alternato", b: "pot", z: ["lombare"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 3, d: "A pancia in giù, braccia avanti. Solleva di poco braccio e gamba opposti, tieni un istante e scendi.", k: "Sollevamento basso, sguardo a terra." },
  { id: "p51", n: "Barchetta", b: "pot", z: ["core"], eq: "none", lv: 3, t: "s", q: 20, d: "Sdraiato sulla schiena, solleva spalle e gambe da terra tenendo la zona lombare appoggiata, braccia tese oltre la testa o lungo i fianchi.", k: "Se la schiena si stacca, piega le ginocchia." },
  { id: "p52", n: "Plank con sollevamento della gamba", b: "pot", z: ["core", "anca"], eq: "none", lv: 3, t: "r", q: 8, u: 1, tp: 3, d: "In plank sugli avambracci, solleva una gamba tesa di pochi centimetri, tieni 1 secondo e riappoggia, alternando.", k: "Il bacino non ruota." },
  { id: "p53", n: "Camminata del contadino", b: "pot", z: ["core", "polso", "spalla"], eq: "manubri", lv: 1, t: "s", q: 40, d: "Un manubrio per mano lungo i fianchi. Cammina a passi normali con il busto alto e le spalle basse.", k: "Postura alta, presa salda." },
  { id: "p54", n: "Camminata con un solo manubrio", b: "pot", z: ["core", "lombare"], eq: "manubri", lv: 2, t: "s", q: 30, u: 1, d: "Un manubrio in una sola mano. Cammina senza inclinarti verso il peso. A metà serie cambia mano.", k: "Spalle allo stesso livello." },
  { id: "p55", n: "Ponte con marcia", b: "pot", z: ["anca", "core"], eq: "none", lv: 2, t: "r", q: 8, u: 1, tp: 4, d: "In posizione di ponte, solleva alternando un piede da terra di pochi centimetri, senza far scendere il bacino.", k: "Bacino alto e fermo." },
  /* anche e glutei */
  { id: "p60", n: "Conchiglia", b: "pot", z: ["anca"], eq: "none", lv: 1, t: "r", q: 15, u: 1, tp: 3, d: "Sdraiato sul fianco, ginocchia piegate e talloni uniti. Apri il ginocchio di sopra come una conchiglia, senza ruotare il bacino, poi chiudi.", k: "Bacino fermo, movimento dall'anca." },
  { id: "p61", n: "Conchiglia con elastico", b: "pot", z: ["anca"], eq: "elastico", lv: 1, t: "r", q: 12, u: 1, tp: 3, d: "Come la conchiglia, con un elastico intorno alle cosce sopra le ginocchia.", k: "Ritorno lento." },
  { id: "p62", n: "Abduzione dell'anca sul fianco", b: "pot", z: ["anca"], eq: "none", lv: 1, t: "r", q: 12, u: 1, tp: 3, d: "Sdraiato sul fianco, gamba di sotto piegata. Solleva la gamba di sopra tesa, con la punta in avanti, leggermente indietro rispetto al corpo.", k: "Punta del piede non rivolta al soffitto." },
  { id: "p63", n: "Passi laterali con elastico", b: "pot", z: ["anca", "ginocchio"], eq: "elastico", lv: 1, t: "r", q: 10, u: 1, tp: 2, d: "Elastico intorno alle caviglie o sopra le ginocchia, gambe semipiegate. Fai passi laterali mantenendo la tensione dell'elastico.", k: "Ginocchia che non cadono verso l'interno." },
  { id: "p64", n: "Ponte con manubrio", b: "pot", z: ["anca", "lombare"], eq: "manubri", lv: 2, t: "r", q: 12, tp: 4, d: "Spalle appoggiate al bordo di un divano o a terra, manubrio appoggiato sul bacino. Solleva il bacino fino ad allineare busto e cosce e scendi.", k: "Mento verso il petto, spingi con i talloni." },
  { id: "p65", n: "Stacco rumeno con manubri", b: "pot", z: ["anca", "lombare"], eq: "manubri", lv: 2, t: "r", q: 10, tp: 4, d: "In piedi, manubri davanti alle cosce, ginocchia morbide. Porta il bacino indietro facendo scendere i pesi lungo le gambe con la schiena dritta, poi risali.", k: "La schiena resta piatta per tutto il movimento." },
  { id: "p66", n: "Stacco su una gamba", b: "pot", z: ["anca", "caviglia", "lombare"], eq: "none", lv: 2, t: "r", q: 8, u: 1, tp: 4, d: "In piedi su una gamba, inclina il busto in avanti mentre l'altra gamba si alza dietro, fino a formare quasi una T. Torna su.", k: "Bacino parallelo al pavimento; tieni un appoggio se serve." },
  { id: "p67", n: "Stacco su una gamba con manubrio", b: "pot", z: ["anca", "caviglia", "lombare"], eq: "manubri", lv: 3, t: "r", q: 8, u: 1, tp: 4, d: "Come lo stacco su una gamba, tenendo un manubrio nella mano opposta alla gamba d'appoggio.", k: "Controllo prima del carico." },
  { id: "p68", n: "Stretta del cuscino tra le ginocchia", b: "pot", z: ["anca", "ginocchio"], eq: "none", lv: 1, t: "r", q: 8, tp: 7, d: "Sdraiato sulla schiena, ginocchia piegate, un cuscino o un pallone tra le ginocchia. Stringi con forza moderata per 5 secondi e rilascia.", k: "Respira normalmente durante la spinta." },
  { id: "p69", n: "Idrante", b: "pot", z: ["anca"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 3, d: "A quattro zampe, solleva di lato il ginocchio piegato senza spostare il peso, poi abbassalo.", k: "Il bacino resta orizzontale." },
  { id: "p70", n: "Slancio posteriore a quattro zampe", b: "pot", z: ["anca"], eq: "none", lv: 1, t: "r", q: 12, u: 1, tp: 3, d: "A quattro zampe, spingi un piede verso il soffitto con il ginocchio piegato, usando il gluteo, poi torna.", k: "Non inarcare la zona lombare." },
  { id: "p71", n: "Plank Copenaghen sul ginocchio", b: "pot", z: ["anca", "core"], eq: "none", lv: 2, t: "s", q: 15, u: 1, d: "Sul fianco, avambraccio a terra, il ginocchio della gamba di sopra appoggiato su una panca o una sedia. Solleva il bacino e tieni.", k: "Corpo in linea; inizia con tempi brevi." },
  /* ginocchia e cosce */
  { id: "p80", n: "Squat a corpo libero", b: "pot", z: ["ginocchio", "anca"], eq: "none", lv: 1, t: "r", q: 12, tp: 3, d: "Piedi alla larghezza delle spalle. Porta il bacino indietro e in basso come per sederti, poi risali spingendo con tutto il piede.", k: "Ginocchia in linea con le punte dei piedi." },
  { id: "p81", n: "Squat con manubrio al petto", b: "pot", z: ["ginocchio", "anca", "core"], eq: "manubri", lv: 2, t: "r", q: 10, tp: 3, d: "Tieni un manubrio verticale contro il petto. Scendi in squat con il busto alto e risali.", k: "Gomiti tra le ginocchia in basso." },
  { id: "p82", n: "Affondo indietro", b: "pot", z: ["ginocchio", "anca"], eq: "none", lv: 1, t: "r", q: 8, u: 1, tp: 3, d: "In piedi, fai un passo lungo indietro e scendi finché entrambe le ginocchia sono piegate a circa 90°. Spingi con la gamba davanti per tornare.", k: "Busto dritto, ginocchio davanti sopra la caviglia." },
  { id: "p83", n: "Affondo laterale", b: "pot", z: ["ginocchio", "anca"], eq: "none", lv: 2, t: "r", q: 8, u: 1, tp: 3, d: "Fai un passo ampio di lato, piega quella gamba portando il bacino indietro, l'altra resta tesa. Spingi per tornare al centro.", k: "Piede e ginocchio rivolti nella stessa direzione." },
  { id: "p84", n: "Affondo in avanti con manubri", b: "pot", z: ["ginocchio", "anca"], eq: "manubri", lv: 2, t: "r", q: 8, u: 1, tp: 3, d: "Manubri lungo i fianchi. Passo lungo in avanti, scendi controllato e spingi con il piede davanti per tornare.", k: "Atterra con tutto il piede." },
  { id: "p85", n: "Squat bulgaro", b: "pot", z: ["ginocchio", "anca"], eq: "none", lv: 3, t: "r", q: 8, u: 1, tp: 3, d: "Collo del piede dietro appoggiato su una sedia o una panca. Scendi piegando la gamba davanti e risali.", k: "Peso sulla gamba davanti." },
  { id: "p86", n: "Squat bulgaro con manubri", b: "pot", z: ["ginocchio", "anca"], eq: "manubri", lv: 3, t: "r", q: 8, u: 1, tp: 3, d: "Come lo squat bulgaro, con un manubrio per mano.", k: "Scendi in controllo, risali deciso." },
  { id: "p87", n: "Salita sul gradino", b: "pot", z: ["ginocchio", "anca"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 3, d: "Davanti a un gradino stabile. Sali spingendo con la gamba sopra il gradino, poi scendi lentamente.", k: "Il ginocchio non cade verso l'interno." },
  { id: "p88", n: "Discesa laterale lenta dal gradino", b: "pot", z: ["ginocchio", "anca"], eq: "none", lv: 2, t: "r", q: 8, u: 1, tp: 5, d: "In piedi di lato su un gradino. Piegando la gamba d'appoggio, scendi lentamente a sfiorare il pavimento con il tallone dell'altra gamba, poi risali.", k: "Discesa in 3 secondi, ginocchio in linea con il piede." },
  { id: "p89", n: "Sedia al muro", b: "pot", z: ["ginocchio"], eq: "none", lv: 1, t: "s", q: 30, d: "Schiena al muro, scivola giù fino a una posizione da seduto (anche meno profonda se è più comodo) e tieni.", k: "Ginocchia sopra le caviglie." },
  { id: "p90", n: "Estensione del ginocchio con elastico", b: "pot", z: ["ginocchio"], eq: "elastico", lv: 1, t: "r", q: 12, u: 1, tp: 3, d: "Seduto, elastico fissato alla gamba della sedia e alla caviglia. Distendi il ginocchio e torna lentamente.", k: "Ritorno controllato." },
  { id: "p91", n: "Flessione del ginocchio con elastico", b: "pot", z: ["ginocchio"], eq: "elastico", lv: 1, t: "r", q: 12, u: 1, tp: 3, d: "A pancia in giù, elastico fissato davanti a te e intorno alla caviglia. Porta il tallone verso il gluteo e torna piano.", k: "Il bacino resta appoggiato." },
  { id: "p92", n: "Ponte con talloni sulla sedia", b: "pot", z: ["ginocchio", "anca"], eq: "none", lv: 2, t: "r", q: 10, tp: 3, d: "Sdraiato sulla schiena, talloni appoggiati sul bordo di una sedia, ginocchia leggermente piegate. Solleva il bacino e scendi.", k: "Senti lavorare il retro della coscia." },
  { id: "p93", n: "Nordic assistito", b: "pot", z: ["ginocchio", "anca"], eq: "none", lv: 3, t: "r", q: 5, tp: 6, d: "In ginocchio su un tappetino, talloni bloccati da un compagno o sotto un mobile pesante. Scendi in avanti con il corpo dritto il più lentamente possibile, frena con le mani e risali aiutandoti.", k: "Scendi solo fin dove controlli il movimento." },
  { id: "p94", n: "Squat con salto controllato", b: "pot", z: ["ginocchio", "caviglia", "anca"], eq: "none", lv: 3, t: "r", q: 6, tp: 4, d: "Mezzo squat, salta verso l'alto e atterra morbido tornando in mezzo squat, fermati 2 secondi prima del salto successivo.", k: "Atterraggio silenzioso, ginocchia in linea." },
  { id: "p95", n: "Balzi laterali con arresto", b: "pot", z: ["ginocchio", "caviglia", "anca"], eq: "none", lv: 3, t: "r", q: 6, u: 1, tp: 4, d: "Su una gamba, balza di lato e atterra sull'altra gamba, fermandoti stabile per 2 secondi.", k: "Atterra con il ginocchio morbido sopra il piede." },
  { id: "p96", n: "Saltello e atterraggio stabile", b: "pot", z: ["ginocchio", "caviglia"], eq: "none", lv: 2, t: "r", q: 8, tp: 4, d: "Piccolo salto in avanti a piedi uniti, atterra morbido e resta fermo 2 secondi in mezzo squat.", k: "Ginocchia che non si avvicinano tra loro." },
  { id: "p97", n: "Split-step con arresto", b: "pot", z: ["ginocchio", "caviglia"], eq: "none", lv: 2, t: "r", q: 8, tp: 4, d: "Piccolo saltello sul posto come nello split-step, atterra sugli avampiedi in posizione di attesa e parti con un passo laterale verso un lato, poi torna.", k: "Atterraggio leggero e pronto." },
  { id: "p98", n: "Isometria del quadricipite", b: "pot", z: ["ginocchio"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 7, d: "Seduto con la gamba tesa, un asciugamano arrotolato sotto il ginocchio. Schiaccia il ginocchio sull'asciugamano contraendo la coscia per 5 secondi e rilascia.", k: "Punta del piede verso di te." },
  { id: "p99", n: "Sollevamento della gamba tesa", b: "pot", z: ["ginocchio", "anca"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 3, d: "Sdraiato sulla schiena, una gamba piegata e l'altra tesa. Contrai la coscia e solleva la gamba tesa fino all'altezza del ginocchio opposto, poi scendi.", k: "Ginocchio ben disteso." },
  /* polpacci, Achille, tibie, caviglie, piede */
  { id: "pa1", n: "Sollevamenti sui talloni", b: "pot", z: ["achille", "caviglia"], eq: "none", lv: 1, t: "r", q: 15, tp: 3, d: "In piedi con un appoggio leggero. Sali sugli avampiedi e scendi lentamente.", k: "Sali dritto, sul primo e secondo dito." },
  { id: "pa2", n: "Sollevamenti sui talloni su una gamba", b: "pot", z: ["achille", "caviglia"], eq: "none", lv: 2, t: "r", q: 12, u: 1, tp: 3, d: "In piedi su una gamba con un appoggio. Sali sull'avampiede e scendi lentamente.", k: "Altezza piena a ogni ripetizione." },
  { id: "pa3", n: "Discesa lenta dei talloni dal gradino", b: "pot", z: ["achille", "caviglia"], eq: "none", lv: 2, t: "r", q: 10, u: 1, tp: 5, d: "Avampiedi sul bordo di un gradino. Sali con due piedi, togli un piede e scendi lentamente sull'altro fin sotto il livello del gradino.", k: "Discesa in 3 secondi, con appoggio per le mani." },
  { id: "pa4", n: "Sollevamenti sui talloni a ginocchia piegate", b: "pot", z: ["achille", "caviglia"], eq: "none", lv: 1, t: "r", q: 15, tp: 3, d: "Ginocchia leggermente piegate (circa 30°), sali sugli avampiedi e scendi mantenendo la piega delle ginocchia. Lavora il muscolo profondo del polpaccio.", k: "Le ginocchia restano piegate." },
  { id: "pa5", n: "Sollevamenti sui talloni con manubri", b: "pot", z: ["achille", "caviglia"], eq: "manubri", lv: 2, t: "r", q: 12, tp: 3, d: "Un manubrio per mano, sali sugli avampiedi e scendi lentamente.", k: "Pausa di 1 secondo in alto." },
  { id: "pa6", n: "Sollevamento delle punte al muro", b: "pot", z: ["tibia", "caviglia"], eq: "none", lv: 1, t: "r", q: 15, tp: 2, d: "Schiena appoggiata al muro, talloni a circa 30 cm dal muro. Solleva le punte dei piedi e riappoggiale.", k: "Talloni sempre a terra." },
  { id: "pa7", n: "Flessione della caviglia con elastico", b: "pot", z: ["tibia", "caviglia"], eq: "elastico", lv: 1, t: "r", q: 15, u: 1, tp: 3, d: "Seduto a gambe tese, elastico fissato davanti e intorno al dorso del piede. Porta la punta verso di te e torna lentamente.", k: "Muove solo la caviglia." },
  { id: "pa8", n: "Eversione con elastico", b: "pot", z: ["caviglia"], eq: "elastico", lv: 1, t: "r", q: 15, u: 1, tp: 3, d: "Seduto, elastico intorno all'avampiede e fissato verso l'interno. Ruota la pianta del piede verso l'esterno e torna.", k: "Il ginocchio non ruota." },
  { id: "pa9", n: "Inversione con elastico", b: "pot", z: ["caviglia"], eq: "elastico", lv: 1, t: "r", q: 15, u: 1, tp: 3, d: "Seduto, elastico intorno all'avampiede e fissato verso l'esterno. Ruota la pianta del piede verso l'interno e torna.", k: "Movimento piccolo e controllato." },
  { id: "pb1", n: "Equilibrio su una gamba", b: "pot", z: ["caviglia", "ginocchio", "anca"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "In piedi su una gamba vicino a un appoggio, ginocchio leggermente morbido. Resta in equilibrio.", k: "Sguardo fisso davanti." },
  { id: "pb2", n: "Equilibrio su una gamba a occhi chiusi", b: "pot", z: ["caviglia", "ginocchio"], eq: "none", lv: 2, t: "s", q: 20, u: 1, d: "Come l'equilibrio su una gamba, ma a occhi chiusi, sempre vicino a un appoggio.", k: "Tieni le mani pronte all'appoggio." },
  { id: "pb3", n: "Tocchi a stella su una gamba", b: "pot", z: ["caviglia", "ginocchio", "anca"], eq: "none", lv: 2, t: "r", q: 6, u: 1, tp: 6, d: "In piedi su una gamba, con l'altro piede tocca leggermente il pavimento davanti, di lato e dietro, tornando ogni volta al centro.", k: "Il ginocchio d'appoggio resta sopra il piede." },
  { id: "pb4", n: "Saltelli sul posto", b: "pot", z: ["achille", "caviglia"], eq: "none", lv: 2, t: "s", q: 20, d: "Piccoli saltelli rapidi e leggeri sugli avampiedi, ginocchia quasi tese, come rimbalzando.", k: "Contatti brevi e silenziosi." },
  { id: "pb5", n: "Piede corto", b: "pot", z: ["caviglia"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 5, d: "Seduto o in piedi, piede appoggiato. Avvicina l'avampiede al tallone sollevando leggermente l'arco plantare, senza piegare le dita. Tieni 3 secondi.", k: "Le dita restano distese." },
  { id: "pb6", n: "Raccogli l'asciugamano con le dita", b: "pot", z: ["caviglia"], eq: "none", lv: 1, t: "s", q: 40, u: 1, d: "Seduto, un asciugamano steso sotto il piede: avvicinalo arricciando le dita.", k: "Tallone fermo a terra." },
  { id: "pb7", n: "Tenuta in punta di piedi", b: "pot", z: ["achille", "caviglia"], eq: "none", lv: 1, t: "r", q: 5, tp: 12, d: "Con un appoggio, sali sugli avampiedi a metà altezza e resta fermo 10 secondi, poi scendi.", k: "Carico distribuito su tutto l'avampiede." },
  { id: "pb8", n: "Marcia con ginocchio alto e tenuta", b: "pot", z: ["anca", "caviglia", "core"], eq: "none", lv: 1, t: "r", q: 10, u: 1, tp: 3, d: "Sali sulla punta di un piede e porta l'altro ginocchio all'altezza dell'anca, tieni 1 secondo e cambia.", k: "Busto alto, bacino fermo." },

  /* ===================== RILASSAMENTO ===================== */
  { id: "r01", n: "Respirazione diaframmatica", b: "ril", z: ["core"], eq: "none", lv: 1, t: "s", q: 90, br: 1, d: "Sdraiato con le ginocchia piegate, una mano sul petto e una sulla pancia. Inspira dal naso gonfiando la pancia, espira lentamente dalla bocca.", k: "La mano sul petto si muove poco." },
  { id: "r02", n: "Respirazione 4-6", b: "ril", z: ["core"], eq: "none", lv: 1, t: "s", q: 60, br: 1, d: "Seduto o sdraiato: inspira contando fino a 4, espira contando fino a 6. Ripeti con calma.", k: "Espirazione più lunga dell'inspirazione." },
  { id: "r03", n: "Respirazione quadrata", b: "ril", z: ["core"], eq: "none", lv: 1, t: "s", q: 60, br: 1, d: "Inspira in 4 tempi, trattieni 4, espira in 4, resta a vuoto 4. Se trattenere è scomodo, riduci a 3 tempi.", k: "Ritmo regolare, senza sforzo." },
  { id: "r04", n: "Rilassamento muscolare progressivo", b: "ril", z: ["core"], eq: "none", lv: 1, t: "s", q: 120, br: 1, d: "Sdraiato. Contrai un gruppo di muscoli per 5 secondi e rilascia per 10: piedi, polpacci, cosce, glutei, pancia, mani, braccia, spalle, viso.", k: "Nota la differenza tra tensione e rilascio." },
  { id: "r05", n: "Scansione del corpo", b: "ril", z: ["core"], eq: "none", lv: 1, t: "s", q: 120, br: 1, d: "Sdraiato a occhi chiusi, porta l'attenzione lentamente dai piedi alla testa, notando le sensazioni di ogni zona e lasciandola andare a ogni espirazione.", k: "Respiro lento e naturale." },
  { id: "r06", n: "Gambe al muro", b: "ril", z: ["achille", "ginocchio"], eq: "none", lv: 1, t: "s", q: 90, br: 1, d: "Sdraiato con il bacino vicino al muro, gambe distese in appoggio sul muro, braccia rilassate. Respira lentamente.", k: "Se tira dietro le gambe, allontanati un po' dal muro." },
  { id: "r07", n: "Posizione del bambino", b: "ril", z: ["lombare", "spalla"], eq: "none", lv: 1, t: "s", q: 45, d: "Seduto sui talloni, porta il busto in avanti e le braccia distese a terra, fronte appoggiata.", k: "Respira verso la schiena." },
  { id: "r08", n: "Allungamento del gluteo a figura 4", b: "ril", z: ["anca", "lombare"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Sdraiato sulla schiena, appoggia una caviglia sul ginocchio opposto e avvicina le gambe al petto tenendo la coscia di sotto.", k: "Allungamento piacevole, mai doloroso." },
  { id: "r09", n: "Allungamento dei femorali con asciugamano", b: "ril", z: ["ginocchio", "anca"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Sdraiato sulla schiena, asciugamano sotto il piede, solleva la gamba tesa finché senti tirare dietro la coscia.", k: "L'altra gamba resta rilassata." },
  { id: "r10", n: "Allungamento del quadricipite in piedi", b: "ril", z: ["ginocchio", "anca"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "In piedi con un appoggio, afferra la caviglia e porta il tallone verso il gluteo, ginocchia vicine.", k: "Bacino in avanti, schiena dritta." },
  { id: "r11", n: "Allungamento dei flessori dell'anca", b: "ril", z: ["anca", "lombare"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "In affondo con il ginocchio dietro a terra su un cuscino. Spingi dolcemente il bacino in avanti stringendo il gluteo della gamba dietro.", k: "Non inarcare la schiena." },
  { id: "r12", n: "Allungamento del polpaccio al muro", b: "ril", z: ["achille", "caviglia"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Mani al muro, una gamba dietro tesa con il tallone a terra, l'altra piegata davanti. Porta il peso in avanti.", k: "Piede dietro rivolto in avanti." },
  { id: "r13", n: "Allungamento del polpaccio a ginocchio piegato", b: "ril", z: ["achille", "caviglia"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Come l'allungamento al muro, ma piega leggermente il ginocchio dietro mantenendo il tallone a terra.", k: "Senti l'allungamento più in basso, vicino al tallone." },
  { id: "r14", n: "Farfalla da seduto", b: "ril", z: ["anca"], eq: "none", lv: 1, t: "s", q: 40, d: "Seduto, piante dei piedi unite e ginocchia aperte. Lascia scendere le ginocchia, con la schiena dritta.", k: "Non spingere le ginocchia con le mani." },
  { id: "r15", n: "Allungamento laterale del busto", b: "ril", z: ["lombare", "spalla"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "In piedi o seduto, braccio teso sopra la testa, inclinati dal lato opposto.", k: "Allunga, non schiacciare il fianco." },
  { id: "r16", n: "Allungamento del petto alla porta", b: "ril", z: ["spalla"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Avambraccio appoggiato allo stipite di una porta, gomito all'altezza della spalla. Ruota piano il busto dal lato opposto.", k: "Spalla bassa e rilassata." },
  { id: "r17", n: "Allungamento con braccio incrociato", b: "ril", z: ["spalla"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Porta il braccio teso davanti al petto e accompagnalo con l'altra mano sopra il gomito.", k: "Spalla lontana dall'orecchio." },
  { id: "r18", n: "Allungamento del tricipite", b: "ril", z: ["spalla", "gomito"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Porta una mano dietro la nuca con il gomito verso l'alto e accompagna il gomito con l'altra mano.", k: "Testa dritta." },
  { id: "r19", n: "Allungamento dei flessori del polso", b: "ril", z: ["gomito", "polso"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Braccio teso davanti, palmo in avanti. Con l'altra mano tira dolcemente le dita verso di te.", k: "Gomito disteso, senza forzare." },
  { id: "r20", n: "Allungamento degli estensori del polso", b: "ril", z: ["gomito", "polso"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Braccio teso davanti, palmo verso il basso. Con l'altra mano piega dolcemente il polso verso il basso.", k: "Allungamento leggero sul dorso dell'avambraccio." },
  { id: "r21", n: "Allungamento laterale del collo", b: "ril", z: ["spalla"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Seduto, porta l'orecchio verso la spalla e lascia scendere la spalla opposta.", k: "Nessuno scatto, solo peso della testa." },
  { id: "r22", n: "Torsione da sdraiato", b: "ril", z: ["lombare", "anca"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Sdraiato sulla schiena, porta un ginocchio piegato verso il lato opposto, braccia aperte e spalle a terra.", k: "Lascia fare alla gravità." },
  { id: "r23", n: "Ginocchia al petto", b: "ril", z: ["lombare"], eq: "none", lv: 1, t: "s", q: 45, d: "Sdraiato sulla schiena, abbraccia le ginocchia e dondola piano.", k: "Respira lentamente." },
  { id: "r24", n: "Allungamento della tibia da seduto sui talloni", b: "ril", z: ["tibia", "caviglia"], eq: "none", lv: 1, t: "s", q: 30, d: "In ginocchio su un tappetino, siediti sui talloni con il dorso dei piedi a terra. Per ridurre l'intensità appoggia le mani a terra.", k: "Solo una sensazione di allungamento sul dorso del piede." },
  { id: "r25", n: "Allungamento laterale dell'anca in piedi", b: "ril", z: ["anca"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "In piedi, incrocia una gamba dietro l'altra e inclina il busto dal lato opposto, spingendo l'anca verso l'esterno.", k: "Usa un appoggio per l'equilibrio." },
  { id: "r26", n: "Allungamento del dorso alla sedia", b: "ril", z: ["spalla", "lombare"], eq: "none", lv: 1, t: "s", q: 40, d: "In piedi davanti a una sedia o un tavolo, mani appoggiate. Porta il bacino indietro e lascia scendere il busto tra le braccia.", k: "Schiena lunga, respira." },
  { id: "r27", n: "Posizione del piccione", b: "ril", z: ["anca"], eq: "none", lv: 2, t: "s", q: 40, u: 1, d: "Da quattro zampe, porta un ginocchio avanti verso la mano dello stesso lato con la gamba piegata davanti, l'altra distesa dietro. Scendi con il busto quanto è comodo.", k: "Se il ginocchio dà fastidio, preferisci la figura 4 da sdraiato." },
  { id: "r28", n: "Allungamento dei femorali in piedi", b: "ril", z: ["ginocchio", "anca"], eq: "none", lv: 1, t: "s", q: 30, u: 1, d: "Tallone su un rialzo basso, gamba tesa. Inclinati in avanti con la schiena dritta finché senti tirare dietro la coscia.", k: "Schiena dritta, non arrotondarla." },
  { id: "r29", n: "Rilassamento a braccia aperte", b: "ril", z: ["spalla", "core"], eq: "none", lv: 1, t: "s", q: 60, br: 1, d: "Sdraiato sulla schiena, braccia aperte con i palmi verso l'alto, gambe distese. Lascia andare il peso del corpo a ogni espirazione.", k: "Spalle che si appoggiano piano a terra." },
  { id: "r30", n: "Gatto e mucca lento con respiro", b: "ril", z: ["lombare"], eq: "none", lv: 1, t: "s", q: 45, d: "A quattro zampe, alterna schiena tonda ed incavata molto lentamente: inspira mentre incavi, espira mentre arrotondi.", k: "Il respiro guida il movimento." }
];

